//! Android: tool discovery (SDK, NDK, JDK, Gradle, cargo-ndk), packaging settings and the
//! Gradle project that turns the game's `cdylib` into an APK or App Bundle.
//!
//! `space3d build --target android` builds the native library with
//! [cargo-ndk](https://github.com/bbqsrc/cargo-ndk) (the NDK's clang as linker, one
//! `jniLibs/<abi>/lib<game>.so` per ABI) and packages it with Gradle and the Android Gradle
//! Plugin ([`AGP_VERSION`]) as a NativeActivity app: no Java or Kotlin code, the library's
//! `android_main` (generated by `space3d::main!`) is the whole app.
//!
//! The Gradle project is either the package's own `android/` directory (what `space3d new`
//! writes; edit it freely) or, for packages without one, generated from
//! `[package.metadata.space3d.android]` into `target/android/<package>/gradle/` on every
//! build. Either way the build passes the library and asset directories as Gradle properties
//! ([`GRADLE_PROPERTIES`]), and all build output stays below `target/android/<package>/`.

use crate::process::{Cmd, Exec, home_dir, which};
use crate::project::{PackageInfo, version_key};
use anyhow::{Context, Result, bail};
use serde_json::Value;
use std::path::{Path, PathBuf};

/// Android Gradle Plugin version of generated projects (latest stable).
pub const AGP_VERSION: &str = "9.4.1";
/// Oldest Gradle that [`AGP_VERSION`] supports.
pub const MIN_GRADLE: (u64, u64, u64) = (9, 1, 0);
/// Oldest JDK that runs [`AGP_VERSION`].
pub const MIN_JAVA: u32 = 17;
/// `compileSdk` of generated projects (Android 17).
pub const COMPILE_SDK: u32 = 37;
/// Default `minSdk` (Android 9: Vulkan 1.1 on most devices, AAudio).
pub const DEFAULT_MIN_SDK: u32 = 28;
/// Default `targetSdk`.
pub const DEFAULT_TARGET_SDK: u32 = 37;
/// NDK releases from r28 link 16 KB-page-aligned libraries by default, which Google Play
/// requires for apps that target Android 15+ devices with 16 KB pages.
pub const MIN_NDK_MAJOR: u64 = 28;
/// Gradle properties `space3d build` passes to the Gradle project.
pub const GRADLE_PROPERTIES: [&str; 5] = [
    "space3d.jniLibs",
    "space3d.assets",
    "space3d.buildDir",
    "space3d.ndkPath",
    "space3d.ndkVersion",
];

/// SDK packages to install (latest stable at the time of writing), for setup messages.
pub const SDK_PACKAGES: &str =
    "\"platform-tools\" \"platforms;android-37.0\" \"build-tools;37.0.0\" \"ndk;30.0.16248370\"";

/// Setup instructions printed when Android tooling is missing.
pub fn setup_instructions() -> String {
    let sdk = default_sdk_dirs()
        .into_iter()
        .next()
        .map_or_else(|| "<sdk dir>".to_owned(), |p| p.display().to_string());
    let (cmdline, jdk, gradle) = if cfg!(target_os = "macos") {
        (
            "brew install --cask android-commandlinetools".to_owned(),
            "brew install openjdk@21".to_owned(),
            "brew install gradle".to_owned(),
        )
    } else {
        (
            "Android Studio (SDK Manager) or the command-line tools from https://developer.android.com/studio"
                .to_owned(),
            "a JDK 17+ (e.g. Temurin 21, or the one bundled with Android Studio)".to_owned(),
            "Gradle 9 (https://gradle.org/install/, e.g. `sdk install gradle`)".to_owned(),
        )
    };
    format!(
        "Android builds need (`space3d doctor --platforms android` checks all of it):
  1. The Android SDK + NDK: install the command-line tools ({cmdline}), then
       sdkmanager --sdk_root={sdk} {SDK_PACKAGES}
     (Android Studio's SDK Manager installs the same). Found in ANDROID_HOME, or in {sdk}.
  2. Java {MIN_JAVA}+: {jdk} (JAVA_HOME, or found automatically)
  3. Gradle: {gradle}
  4. cargo install cargo-ndk --locked
  5. rustup target add aarch64-linux-android
Then: space3d build --target android [--release]   (APK in dist/android/)"
    )
}

// ------------------------------------------------------------------------------------ ABIs

/// An Android ABI and its Rust target.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Abi {
    /// 64-bit ARM (all current phones; the Apple silicon emulator).
    Arm64,
    /// 32-bit ARM (old phones).
    Armv7,
    /// 64-bit x86 (emulators on Intel/AMD hosts, Chromebooks).
    X86_64,
    /// 32-bit x86.
    X86,
}

impl Abi {
    /// Every ABI.
    pub const ALL: [Abi; 4] = [Abi::Arm64, Abi::Armv7, Abi::X86_64, Abi::X86];

    /// Android's name (`jniLibs/<name>/`).
    pub fn name(self) -> &'static str {
        match self {
            Abi::Arm64 => "arm64-v8a",
            Abi::Armv7 => "armeabi-v7a",
            Abi::X86_64 => "x86_64",
            Abi::X86 => "x86",
        }
    }

    /// The Rust target triple.
    pub fn rust_target(self) -> &'static str {
        match self {
            Abi::Arm64 => "aarch64-linux-android",
            Abi::Armv7 => "armv7-linux-androideabi",
            Abi::X86_64 => "x86_64-linux-android",
            Abi::X86 => "i686-linux-android",
        }
    }

    /// Parse an ABI name or Rust triple.
    pub fn parse(s: &str) -> Option<Abi> {
        Abi::ALL.into_iter().find(|a| a.name() == s || a.rust_target() == s)
    }
}

// ------------------------------------------------------------------------------------ tools

/// Where the Android SDK was found.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Sdk {
    /// SDK root.
    pub dir: PathBuf,
    /// How it was found (`ANDROID_HOME`, `ANDROID_SDK_ROOT` or `default location`).
    pub source: &'static str,
}

/// Default SDK locations: Android Studio's, then (macOS) Homebrew's command-line tools root.
pub fn default_sdk_dirs() -> Vec<PathBuf> {
    let mut dirs = Vec::new();
    if cfg!(windows) {
        if let Some(local) = std::env::var_os("LOCALAPPDATA") {
            dirs.push(PathBuf::from(local).join("Android").join("Sdk"));
        }
    } else if let Some(home) = home_dir() {
        if cfg!(target_os = "macos") {
            dirs.push(home.join("Library/Android/sdk"));
        } else {
            dirs.push(home.join("Android/Sdk"));
        }
    }
    if cfg!(target_os = "macos") {
        for prefix in ["/opt/homebrew", "/usr/local"] {
            dirs.push(Path::new(prefix).join("share/android-commandlinetools"));
        }
    }
    dirs
}

/// The Android SDK: `ANDROID_HOME`, `ANDROID_SDK_ROOT`, else a [default location](default_sdk_dirs)
/// that has SDK packages in it.
pub fn sdk() -> Option<Sdk> {
    for var in ["ANDROID_HOME", "ANDROID_SDK_ROOT"] {
        if let Some(dir) = std::env::var_os(var).map(PathBuf::from).filter(|p| p.is_dir()) {
            return Some(Sdk { dir, source: var });
        }
    }
    default_sdk_dirs()
        .into_iter()
        .find(|d| {
            ["platforms", "ndk", "platform-tools", "build-tools"]
                .iter()
                .any(|s| d.join(s).is_dir())
        })
        .map(|dir| Sdk {
            dir,
            source: "default location",
        })
}

/// The newest `<dir>/<version>` subdirectory (NDKs, build-tools) by numeric version.
pub fn newest_version_dir(dir: &Path) -> Option<(PathBuf, String)> {
    std::fs::read_dir(dir)
        .ok()?
        .filter_map(|e| e.ok().map(|e| e.path()))
        .filter(|p| p.is_dir())
        .filter_map(|p| {
            let name = p.file_name()?.to_str()?.to_owned();
            name.chars().next()?.is_ascii_digit().then_some((p, name))
        })
        .max_by_key(|(_, name)| version_key(name))
}

/// The newest installed SDK platform (`platforms/android-<api>`), e.g. `android-37.0`.
pub fn newest_platform(sdk: &Path) -> Option<String> {
    std::fs::read_dir(sdk.join("platforms"))
        .ok()?
        .filter_map(|e| e.ok()?.file_name().into_string().ok())
        .filter_map(|n| {
            let api = n.strip_prefix("android-")?;
            api.chars()
                .next()?
                .is_ascii_digit()
                .then(|| (version_key(api), n.clone()))
        })
        .max()
        .map(|(_, n)| n)
}

/// The Android NDK: `ANDROID_NDK_ROOT` / `ANDROID_NDK_HOME` / `NDK_HOME`, else the newest
/// `<sdk>/ndk/<version>` (or the legacy `<sdk>/ndk-bundle`).
pub fn ndk(sdk: Option<&Path>) -> Option<PathBuf> {
    ["ANDROID_NDK_ROOT", "ANDROID_NDK_HOME", "NDK_HOME"]
        .iter()
        .filter_map(std::env::var_os)
        .map(PathBuf::from)
        .find(|p| p.is_dir())
        .or_else(|| {
            let sdk = sdk?;
            newest_version_dir(&sdk.join("ndk"))
                .map(|(p, _)| p)
                .or_else(|| Some(sdk.join("ndk-bundle")).filter(|p| p.is_dir()))
        })
}

/// `Pkg.Revision` of an SDK package's `source.properties` (e.g. the NDK's `30.0.16248370`).
pub fn parse_pkg_revision(properties: &str) -> Option<String> {
    properties.lines().find_map(|l| {
        let (key, value) = l.split_once('=')?;
        (key.trim() == "Pkg.Revision").then(|| value.trim().to_owned())
    })
}

/// Version of the NDK in `ndk_dir`.
pub fn ndk_version(ndk_dir: &Path) -> Option<String> {
    parse_pkg_revision(&std::fs::read_to_string(ndk_dir.join("source.properties")).ok()?)
}

/// A JDK: its home (when found outside `PATH`) and major version.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Java {
    /// `JAVA_HOME` to pass to Gradle (`None`: the `java` on `PATH` works).
    pub home: Option<PathBuf>,
    /// Major version (17, 21, 25, ...).
    pub version: u32,
    /// How it was found.
    pub source: String,
}

/// Parse the major version from `java -version` output
/// (`openjdk version "21.0.12.1" 2026-08-18`, `java version "1.8.0_402"`).
pub fn parse_java_version(s: &str) -> Option<u32> {
    let quoted = s.lines().find(|l| l.contains("version"))?.split('"').nth(1)?;
    let mut parts = quoted.split(['.', '_', '-', '+']);
    let first: u32 = parts.next()?.parse().ok()?;
    if first == 1 {
        parts.next()?.parse().ok()
    } else {
        Some(first)
    }
}

fn java_version_of(java: &Path) -> Option<u32> {
    // `java -version` prints to stderr; `probe` falls back to it when stdout is empty.
    parse_java_version(&crate::process::probe(&Cmd::new(java).arg("-version"))?)
}

/// JDK homes worth trying when `JAVA_HOME` is unset and `java` is not usable: Android Studio's
/// bundled JBR, Homebrew's `openjdk` kegs (newest first), `/usr/lib/jvm/*`.
pub fn candidate_java_homes() -> Vec<PathBuf> {
    let mut homes = Vec::new();
    if cfg!(target_os = "macos") {
        homes.push(PathBuf::from(
            "/Applications/Android Studio.app/Contents/jbr/Contents/Home",
        ));
        for prefix in ["/opt/homebrew/opt", "/usr/local/opt"] {
            let mut kegs: Vec<(u64, PathBuf)> = std::fs::read_dir(prefix)
                .into_iter()
                .flatten()
                .filter_map(|e| {
                    let name = e.ok()?.file_name().into_string().ok()?;
                    let version = match name.strip_prefix("openjdk") {
                        Some("") => u64::MAX,
                        Some(v) => v.strip_prefix('@')?.parse().ok()?,
                        None => return None,
                    };
                    Some((
                        version,
                        Path::new(prefix).join(&name).join("libexec/openjdk.jdk/Contents/Home"),
                    ))
                })
                .collect();
            kegs.sort_by_key(|k| std::cmp::Reverse(k.0));
            homes.extend(kegs.into_iter().map(|(_, p)| p));
        }
    } else if cfg!(windows) {
        if let Some(pf) = std::env::var_os("ProgramFiles") {
            homes.push(PathBuf::from(pf).join("Android").join("Android Studio").join("jbr"));
        }
    } else {
        homes.push(PathBuf::from("/opt/android-studio/jbr"));
        if let Some(home) = home_dir() {
            homes.push(home.join("android-studio/jbr"));
        }
        let mut jvms: Vec<PathBuf> = std::fs::read_dir("/usr/lib/jvm")
            .into_iter()
            .flatten()
            .filter_map(|e| e.ok().map(|e| e.path()))
            .collect();
        jvms.sort();
        homes.extend(jvms.into_iter().rev());
    }
    homes
}

/// A usable JDK ≥ [`MIN_JAVA`] (else the best one found, so the caller can report its version):
/// `JAVA_HOME`, the `java` on `PATH`, then [`candidate_java_homes`]. macOS' `/usr/bin/java`
/// is only a stub without an installed JDK, so it counts only when it runs.
pub fn java() -> Option<Java> {
    let exe = |home: &Path| home.join("bin").join(if cfg!(windows) { "java.exe" } else { "java" });
    let mut found: Vec<Java> = Vec::new();
    if let Some(home) = std::env::var_os("JAVA_HOME").map(PathBuf::from)
        && let Some(version) = java_version_of(&exe(&home))
    {
        found.push(Java {
            home: Some(home),
            version,
            source: "JAVA_HOME".into(),
        });
    }
    if found.iter().all(|j| j.version < MIN_JAVA)
        && let Some(path) = which("java")
        && let Some(version) = java_version_of(&path)
    {
        found.push(Java {
            home: None,
            version,
            source: path.display().to_string(),
        });
    }
    if found.iter().all(|j| j.version < MIN_JAVA) {
        for home in candidate_java_homes() {
            if let Some(version) = java_version_of(&exe(&home)) {
                found.push(Java {
                    source: home.display().to_string(),
                    home: Some(home),
                    version,
                });
                if version >= MIN_JAVA {
                    break;
                }
            }
        }
    }
    found
        .iter()
        .find(|j| j.version >= MIN_JAVA)
        .or_else(|| found.iter().max_by_key(|j| j.version))
        .cloned()
}

/// Parse `gradle --version` (`Gradle 9.7.1`).
pub fn parse_gradle_version(s: &str) -> Option<(u64, u64, u64)> {
    let v = s.lines().find_map(|l| l.trim().strip_prefix("Gradle "))?;
    v.chars().next()?.is_ascii_digit().then(|| version_key(v.trim()))
}

/// The Gradle to run for a project: its wrapper (`gradlew`) if it has one, else `gradle` on
/// `PATH`.
pub fn gradle_program(project_dir: &Path) -> Option<PathBuf> {
    let wrapper = project_dir.join(if cfg!(windows) { "gradlew.bat" } else { "gradlew" });
    if wrapper.is_file() {
        return Some(wrapper);
    }
    which("gradle")
}

/// `gradle --version` of `program` (with `java_home`, which Gradle needs to start).
pub fn gradle_version(exec: &Exec, program: &Path, java_home: Option<&Path>) -> Option<(u64, u64, u64)> {
    let mut cmd = Cmd::new(program).args(["--version", "--quiet"]);
    if let Some(home) = java_home {
        cmd = cmd.env("JAVA_HOME", home);
    }
    parse_gradle_version(&exec.probe(&cmd)?)
}

/// Parse `cargo ndk --version` (`cargo-ndk 4.1.2`).
pub fn parse_cargo_ndk_version(s: &str) -> Option<String> {
    let v = s.lines().next()?.trim().strip_prefix("cargo-ndk ")?;
    v.chars().next()?.is_ascii_digit().then(|| v.trim().to_owned())
}

/// Installed cargo-ndk version (`None`: not installed).
pub fn cargo_ndk_version(exec: &Exec) -> Option<String> {
    which("cargo-ndk")?;
    parse_cargo_ndk_version(&exec.probe(&Cmd::cargo("ndk").arg("--version"))?)
}

// ------------------------------------------------------------------------------------ config

/// Packaging settings of an Android app, from `[package.metadata.space3d.android]` (or the
/// older cargo-apk `[package.metadata.android]`) with defaults.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct AndroidConfig {
    /// Application id / package name (`com.example.my_game`).
    pub application_id: String,
    /// App name on the launcher.
    pub label: String,
    /// File name of the APK/AAB without extension.
    pub apk_name: String,
    /// `versionName` (default: the package version).
    pub version_name: String,
    /// `versionCode` (default: from the package version, `major·10⁶ + minor·10³ + patch`).
    pub version_code: u32,
    /// `minSdk` (also the API level the native library is linked against).
    pub min_sdk: u32,
    /// `targetSdk`.
    pub target_sdk: u32,
    /// `android:screenOrientation` (`unspecified`, `landscape`, `sensorLandscape`, ...).
    pub orientation: String,
    /// `uses-permission`s.
    pub permissions: Vec<String>,
    /// ABIs to build (default arm64-v8a).
    pub abis: Vec<Abi>,
    /// Directory packaged as the APK's `assets/` (`None`: no assets).
    pub assets: Option<PathBuf>,
    /// Launcher icon (PNG), generated projects only.
    pub icon: Option<PathBuf>,
}

fn meta_table(pkg: &PackageInfo) -> Option<(&Value, bool)> {
    let m = &pkg.metadata;
    if let Some(t) = m
        .get("space3d")
        .and_then(|s| s.get("android"))
        .filter(|t| t.is_object())
    {
        return Some((t, false));
    }
    m.get("android").filter(|t| t.is_object()).map(|t| (t, true))
}

fn str_at<'a>(v: &'a Value, path: &[&str]) -> Option<&'a str> {
    path.iter().try_fold(v, |v, k| v.get(k))?.as_str()
}

fn u32_at(v: &Value, path: &[&str]) -> Option<u32> {
    path.iter()
        .try_fold(v, |v, k| v.get(k))?
        .as_u64()
        .and_then(|n| u32::try_from(n).ok())
}

/// `versionCode` for a semver version: `major·1 000 000 + minor·1 000 + patch` (at least 1).
pub fn version_code(version: &str) -> u32 {
    let (major, minor, patch) = version_key(version);
    let code = major.min(2099) * 1_000_000 + minor.min(999) * 1_000 + patch.min(999);
    u32::try_from(code.max(1)).unwrap_or(1)
}

/// A valid application id from a crate name: `com.example.<name>` (lower case, `-` → `_`).
pub fn default_application_id(crate_name: &str) -> String {
    let mut segment: String = crate_name
        .to_ascii_lowercase()
        .chars()
        .map(|c| if c.is_ascii_alphanumeric() { c } else { '_' })
        .collect();
    if !segment.starts_with(|c: char| c.is_ascii_alphabetic()) {
        segment.insert(0, 'g');
    }
    format!("com.example.{segment}")
}

/// Check an application id: two or more `.`-separated segments, each a letter followed by
/// letters, digits or `_`.
pub fn validate_application_id(id: &str) -> Result<()> {
    let ok = id.split('.').count() >= 2
        && id.split('.').all(|s| {
            s.starts_with(|c: char| c.is_ascii_alphabetic()) && s.chars().all(|c| c.is_ascii_alphanumeric() || c == '_')
        });
    if !ok {
        bail!("invalid Android application id `{id}` (expected e.g. com.example.my_game)");
    }
    Ok(())
}

/// Title-case a package name for the launcher (`my_game` → `My Game`).
fn title(name: &str) -> String {
    name.split(['-', '_'])
        .filter(|w| !w.is_empty())
        .map(|w| {
            let mut c = w.chars();
            c.next()
                .map(|f| f.to_uppercase().chain(c).collect::<String>())
                .unwrap_or_default()
        })
        .collect::<Vec<_>>()
        .join(" ")
}

impl AndroidConfig {
    /// Settings for `game` packaged from `lib` (the package that builds the `cdylib`: `game`
    /// itself or its `-mobile` crate). Metadata is read from `lib`, then `game`.
    pub fn from_packages(lib: &PackageInfo, game: &PackageInfo) -> Result<Self> {
        let found = meta_table(lib)
            .map(|(t, legacy)| (t, legacy, lib))
            .or_else(|| meta_table(game).map(|(t, legacy)| (t, legacy, game)));
        let null = Value::Null;
        let (t, legacy, owner) = found.unwrap_or((&null, false, game));
        let s = |modern: &[&str], old: &[&str]| {
            if legacy { str_at(t, old) } else { str_at(t, modern) }
        };
        let application_id = s(&["application_id"], &["package"])
            .or_else(|| str_at(t, &["package"]))
            .map(str::to_owned)
            .unwrap_or_else(|| default_application_id(&game.name));
        validate_application_id(&application_id)?;
        let label = s(&["label"], &["application", "label"])
            .map(str::to_owned)
            .unwrap_or_else(|| title(&game.name));
        let apk_name = str_at(t, &["apk_name"]).unwrap_or(&game.name).to_owned();
        let version_name = str_at(t, &["version_name"]).unwrap_or(&game.version).to_owned();
        let version_code = u32_at(t, &["version_code"]).unwrap_or_else(|| version_code(&game.version));
        let (min_sdk, target_sdk) = if legacy {
            (
                u32_at(t, &["sdk", "min_sdk_version"]),
                u32_at(t, &["sdk", "target_sdk_version"]),
            )
        } else {
            (u32_at(t, &["min_sdk"]), u32_at(t, &["target_sdk"]))
        };
        let min_sdk = min_sdk.unwrap_or(DEFAULT_MIN_SDK);
        let target_sdk = target_sdk.unwrap_or(DEFAULT_TARGET_SDK).max(min_sdk);
        let orientation = s(&["orientation"], &["application", "activity", "orientation"])
            .unwrap_or("unspecified")
            .to_owned();
        if orientation.is_empty() || !orientation.chars().all(|c| c.is_ascii_alphabetic()) {
            bail!(
                "invalid Android orientation `{orientation}` (e.g. unspecified, landscape, sensorLandscape, portrait)"
            );
        }
        let permissions: Vec<String> = if legacy {
            t.get("uses_permission")
                .and_then(Value::as_array)
                .map(|a| {
                    a.iter()
                        .filter_map(|p| p.get("name")?.as_str().map(str::to_owned))
                        .collect()
                })
                .unwrap_or_default()
        } else {
            t.get("permissions")
                .and_then(Value::as_array)
                .map(|a| a.iter().filter_map(|p| p.as_str().map(str::to_owned)).collect())
                .unwrap_or_else(|| vec!["android.permission.INTERNET".into()])
        };
        let abi_list = t
            .get(if legacy { "build_targets" } else { "abis" })
            .and_then(Value::as_array);
        let abis = match abi_list {
            Some(list) => list
                .iter()
                .map(|v| {
                    let s = v.as_str().unwrap_or_default();
                    Abi::parse(s)
                        .with_context(|| format!("unknown Android ABI `{s}` (arm64-v8a, armeabi-v7a, x86_64, x86)"))
                })
                .collect::<Result<Vec<_>>>()?,
            None => vec![Abi::Arm64],
        };
        if abis.is_empty() {
            bail!("no Android ABIs configured");
        }
        let assets = match str_at(t, &["assets"]) {
            Some(p) => Some(owner.dir().join(p)),
            None => Some(game.dir().join("assets")),
        }
        .filter(|p| p.is_dir());
        let icon = str_at(t, &["icon"]).map(|p| owner.dir().join(p));
        Ok(Self {
            application_id,
            label,
            apk_name,
            version_name,
            version_code,
            min_sdk,
            target_sdk,
            orientation,
            permissions,
            abis,
            assets,
            icon,
        })
    }
}

// ------------------------------------------------------------------------------------ gradle

/// Where generated build files point by default (the build passes the real directories as
/// [`GRADLE_PROPERTIES`]; the defaults serve IDEs and CI jobs running Gradle directly).
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct GradleDefaults {
    /// `jniLibs` directory (relative to the Gradle project, or absolute).
    pub jni_libs: String,
    /// Assets directory, if any.
    pub assets: Option<String>,
}

fn xml_escape(s: &str) -> String {
    s.replace('&', "&amp;")
        .replace('<', "&lt;")
        .replace('>', "&gt;")
        .replace('"', "&quot;")
        .replace('\'', "&apos;")
}

fn kotlin_string(s: &str) -> String {
    let escaped = s.replace('\\', "\\\\").replace('"', "\\\"").replace('$', "\\$");
    format!("\"{escaped}\"")
}

/// The files of a Gradle project that packages the library `lib<lib_name>.so` as a
/// NativeActivity app (paths relative to the project directory).
pub fn gradle_project(
    cfg: &AndroidConfig,
    lib_name: &str,
    project_name: &str,
    defaults: &GradleDefaults,
) -> Vec<(PathBuf, String)> {
    let settings = format!(
        r#"// Gradle settings of the Android app (Space3d). Build it with `space3d build --target android`.
pluginManagement {{
    repositories {{
        google()
        mavenCentral()
        gradlePluginPortal()
    }}
}}
dependencyResolutionManagement {{
    repositoriesMode.set(RepositoriesMode.FAIL_ON_PROJECT_REPOS)
    repositories {{
        google()
        mavenCentral()
    }}
}}
rootProject.name = {name}
"#,
        name = kotlin_string(project_name)
    );
    let assets_default = defaults
        .assets
        .as_deref()
        .map_or_else(|| "\"\"".to_owned(), kotlin_string);
    let build = format!(
        r#"// The Android app (Space3d): a NativeActivity whose code is the Rust library
// `lib{lib_name}.so` (built by `space3d build --target android` with cargo-ndk), plus the game's
// assets. No Java or Kotlin code.
//
// `space3d build` passes the directories below as Gradle properties; the defaults suit
// running Gradle directly after `cargo ndk -o <jniLibs dir> ...` (CI, Android Studio).
plugins {{
    id("com.android.application") version "{AGP_VERSION}"
}}

val space3dJniLibs = providers.gradleProperty("space3d.jniLibs").getOrElse({jni})
val space3dAssets = providers.gradleProperty("space3d.assets").getOrElse({assets_default})
providers.gradleProperty("space3d.buildDir").orNull?.let {{ layout.buildDirectory.set(file(it)) }}

// Release signing: a keystore from the environment, else the debug key (installable, not
// for Google Play).
val releaseKeystore = providers.environmentVariable("SPACE3D_ANDROID_KEYSTORE").orNull

android {{
    namespace = {app_id}
    compileSdk = {COMPILE_SDK}
    // The NDK that built the library strips its debug symbols in the APK (`space3d build`
    // passes it; the unstripped library stays in target/ for symbolizing crashes).
    providers.gradleProperty("space3d.ndkPath").orNull?.let {{ ndkPath = it }}
    providers.gradleProperty("space3d.ndkVersion").orNull?.let {{ ndkVersion = it }}

    defaultConfig {{
        applicationId = {app_id}
        minSdk = {min_sdk}
        targetSdk = {target_sdk}
        versionCode = {version_code}
        versionName = {version_name}
    }}

    sourceSets {{
        getByName("main") {{
            jniLibs.directories.add(space3dJniLibs)
            if (space3dAssets.isNotEmpty() && file(space3dAssets).isDirectory) {{
                assets.directories.add(space3dAssets)
            }}
        }}
    }}

    signingConfigs {{
        if (releaseKeystore != null) {{
            create("release") {{
                storeFile = file(releaseKeystore)
                storePassword = providers.environmentVariable("SPACE3D_ANDROID_KEYSTORE_PASSWORD").orNull
                keyAlias = providers.environmentVariable("SPACE3D_ANDROID_KEY_ALIAS").orNull
                keyPassword = providers.environmentVariable("SPACE3D_ANDROID_KEY_PASSWORD").orNull
                    ?: providers.environmentVariable("SPACE3D_ANDROID_KEYSTORE_PASSWORD").orNull
            }}
        }}
    }}

    buildTypes {{
        getByName("release") {{
            signingConfig = signingConfigs.findByName("release") ?: signingConfigs.getByName("debug")
        }}
    }}
}}
"#,
        jni = kotlin_string(&defaults.jni_libs),
        app_id = kotlin_string(&cfg.application_id),
        min_sdk = cfg.min_sdk,
        target_sdk = cfg.target_sdk,
        version_code = cfg.version_code,
        version_name = kotlin_string(&cfg.version_name),
    );
    let properties = "# Gradle settings of the Android app (Space3d).
org.gradle.jvmargs=-Xmx2g -Dfile.encoding=UTF-8
org.gradle.configuration-cache=true
# No Kotlin or Java code (NativeActivity): keep the Kotlin standard library out of the APK.
android.builtInKotlin=false
"
    .to_owned();
    let permissions: String = cfg
        .permissions
        .iter()
        .map(|p| format!("    <uses-permission android:name=\"{}\" />\n", xml_escape(p)))
        .collect();
    let icon = if cfg.icon.is_some() {
        "\n        android:icon=\"@mipmap/ic_launcher\""
    } else {
        ""
    };
    let manifest = format!(
        r#"<?xml version="1.0" encoding="utf-8"?>
<!-- The Android app (Space3d): NativeActivity loads lib{lib_name}.so, whose `android_main`
     (generated by `space3d::main!`) runs the game. -->
<manifest xmlns:android="http://schemas.android.com/apk/res/android">
    <!-- wgpu renders with Vulkan, or OpenGL ES 3 where Vulkan is missing or unusable. -->
    <uses-feature android:glEsVersion="0x00030000" android:required="true" />
{permissions}
    <!-- enableOnBackInvokedCallback="false": Back reaches the game as a key
         (`KeyCode::BrowserBack`) instead of closing the activity (predictive back). -->
    <application
        android:label="{label}"{icon}
        android:hasCode="false"
        android:appCategory="game"
        android:enableOnBackInvokedCallback="false"
        android:theme="@android:style/Theme.DeviceDefault.NoActionBar.Fullscreen">
        <!-- configChanges: rotation, resizing and keyboards reach the game as events instead
             of restarting the activity. -->
        <activity
            android:name="android.app.NativeActivity"
            android:exported="true"
            android:launchMode="singleTask"
            android:screenOrientation="{orientation}"
            android:configChanges="orientation|screenSize|screenLayout|smallestScreenSize|density|keyboard|keyboardHidden|navigation|uiMode">
            <meta-data android:name="android.app.lib_name" android:value="{lib_name}" />
            <intent-filter>
                <action android:name="android.intent.action.MAIN" />
                <category android:name="android.intent.category.LAUNCHER" />
            </intent-filter>
        </activity>
    </application>
</manifest>
"#,
        label = xml_escape(&cfg.label),
        orientation = cfg.orientation,
    );
    let gitignore = "build/\n.gradle/\n.kotlin/\nlocal.properties\n".to_owned();
    vec![
        (PathBuf::from("settings.gradle.kts"), settings),
        (PathBuf::from("build.gradle.kts"), build),
        (PathBuf::from("gradle.properties"), properties),
        (PathBuf::from("src/main/AndroidManifest.xml"), manifest),
        (PathBuf::from(".gitignore"), gitignore),
    ]
}

/// A package's own Gradle project: `<dir>/android/` with a `build.gradle(.kts)`.
pub fn own_gradle_project(package_dir: &Path) -> Option<PathBuf> {
    let dir = package_dir.join("android");
    ["build.gradle.kts", "build.gradle"]
        .iter()
        .any(|f| dir.join(f).is_file())
        .then_some(dir)
}

/// Write `files` below `root`, leaving files whose content is unchanged untouched (so Gradle
/// sees no change).
pub fn write_files(root: &Path, files: &[(PathBuf, String)]) -> Result<()> {
    for (rel, content) in files {
        let path = root.join(rel);
        if std::fs::read_to_string(&path).is_ok_and(|old| old == *content) {
            continue;
        }
        if let Some(parent) = path.parent() {
            std::fs::create_dir_all(parent).with_context(|| format!("creating {}", parent.display()))?;
        }
        std::fs::write(&path, content).with_context(|| format!("writing {}", path.display()))?;
    }
    Ok(())
}

/// The Gradle task: `assemble`/`bundle` + `Debug`/`Release`.
pub fn gradle_task(release: bool, bundle: bool) -> String {
    format!(
        "{}{}",
        if bundle { "bundle" } else { "assemble" },
        if release { "Release" } else { "Debug" }
    )
}

/// Files with `extension` directly in `dir`, sorted.
pub fn outputs(dir: &Path, extension: &str) -> Vec<PathBuf> {
    let mut files: Vec<PathBuf> = std::fs::read_dir(dir)
        .into_iter()
        .flatten()
        .filter_map(|e| e.ok().map(|e| e.path()))
        .filter(|p| p.extension().is_some_and(|e| e == extension))
        .collect();
    files.sort();
    files
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::project::TargetInfo;

    fn package(name: &str, dir: &Path, metadata: Value) -> PackageInfo {
        PackageInfo {
            name: name.into(),
            version: "1.2.3".into(),
            manifest_path: dir.join("Cargo.toml"),
            targets: vec![TargetInfo {
                name: name.replace('-', "_"),
                kind: vec!["lib".into()],
                crate_types: vec!["lib".into()],
            }],
            metadata,
        }
    }

    #[test]
    fn abis_parse_names_and_triples() {
        assert_eq!(Abi::parse("arm64-v8a"), Some(Abi::Arm64));
        assert_eq!(Abi::parse("x86_64-linux-android"), Some(Abi::X86_64));
        assert_eq!(Abi::parse("mips"), None);
        for abi in Abi::ALL {
            assert_eq!(Abi::parse(abi.name()), Some(abi));
            assert_eq!(Abi::parse(abi.rust_target()), Some(abi));
        }
    }

    #[test]
    fn versions_parse() {
        assert_eq!(
            parse_java_version("openjdk version \"21.0.12.1\" 2026-08-18\nOpenJDK Runtime"),
            Some(21)
        );
        assert_eq!(parse_java_version("java version \"1.8.0_402\""), Some(8));
        assert_eq!(parse_java_version("openjdk version \"25\" 2025-09-16"), Some(25));
        assert_eq!(
            parse_java_version("The operation couldn't be completed. Unable to locate a Java Runtime."),
            None
        );
        assert_eq!(
            parse_gradle_version(
                "\n------------------------------------------------------------\nGradle 9.7.1\n------"
            ),
            Some((9, 7, 1))
        );
        assert_eq!(parse_gradle_version("Gradle 10.0"), Some((10, 0, 0)));
        assert_eq!(parse_gradle_version("nope"), None);
        assert_eq!(parse_cargo_ndk_version("cargo-ndk 4.1.2").as_deref(), Some("4.1.2"));
        assert_eq!(parse_cargo_ndk_version("error"), None);
        assert_eq!(
            parse_pkg_revision("Pkg.Desc = Android NDK\nPkg.Revision = 30.0.16248370\n").as_deref(),
            Some("30.0.16248370")
        );
        assert_eq!(parse_pkg_revision("Pkg.Revision=37.1.11").as_deref(), Some("37.1.11"));
        assert_eq!(version_code("0.1.0"), 1_000);
        assert_eq!(version_code("1.2.3"), 1_002_003);
        assert_eq!(version_code("0.0.0"), 1);
    }

    #[test]
    fn newest_versions_sort_numerically() {
        let dir = tempfile::tempdir().unwrap();
        for v in ["9.1.0", "28.2.13676358", "30.0.16248370", "junk"] {
            std::fs::create_dir_all(dir.path().join("ndk").join(v)).unwrap();
        }
        for p in ["android-9", "android-36", "android-37.0", "android-37.2-beta3"] {
            std::fs::create_dir_all(dir.path().join("platforms").join(p)).unwrap();
        }
        let (path, version) = newest_version_dir(&dir.path().join("ndk")).unwrap();
        assert_eq!(version, "30.0.16248370");
        assert!(path.ends_with("30.0.16248370"));
        assert_eq!(newest_platform(dir.path()).as_deref(), Some("android-37.2-beta3"));
        assert_eq!(newest_version_dir(&dir.path().join("missing")), None);
    }

    #[test]
    fn application_ids() {
        assert_eq!(default_application_id("my-game"), "com.example.my_game");
        assert_eq!(default_application_id("3d_demo"), "com.example.g3d_demo");
        assert!(validate_application_id("com.example.my_game").is_ok());
        assert!(validate_application_id("dev.space3d.examples.hello_cube").is_ok());
        assert!(validate_application_id("nodots").is_err());
        assert!(validate_application_id("com.3d.game").is_err());
        assert!(validate_application_id("com.my-game.x").is_err());
    }

    #[test]
    fn config_defaults_and_metadata() {
        let dir = tempfile::tempdir().unwrap();
        std::fs::create_dir_all(dir.path().join("assets")).unwrap();
        let game = package("my-game", dir.path(), Value::Null);
        let cfg = AndroidConfig::from_packages(&game, &game).unwrap();
        assert_eq!(cfg.application_id, "com.example.my_game");
        assert_eq!(cfg.label, "My Game");
        assert_eq!(cfg.apk_name, "my-game");
        assert_eq!((cfg.min_sdk, cfg.target_sdk), (DEFAULT_MIN_SDK, DEFAULT_TARGET_SDK));
        assert_eq!(cfg.version_code, 1_002_003);
        assert_eq!(cfg.abis, [Abi::Arm64]);
        assert_eq!(cfg.orientation, "unspecified");
        assert_eq!(cfg.permissions, ["android.permission.INTERNET"]);
        assert_eq!(cfg.assets, Some(dir.path().join("assets")));

        let meta = serde_json::json!({"space3d": {"android": {
            "application_id": "dev.space3d.examples.cube",
            "label": "Cube",
            "min_sdk": 30,
            "orientation": "landscape",
            "permissions": [],
            "abis": ["arm64-v8a", "x86_64"],
            "assets": "missing",
            "version_code": 7
        }}});
        let cfg = AndroidConfig::from_packages(&package("cube", dir.path(), meta), &game).unwrap();
        assert_eq!(cfg.application_id, "dev.space3d.examples.cube");
        assert_eq!((cfg.label.as_str(), cfg.min_sdk, cfg.version_code), ("Cube", 30, 7));
        assert_eq!(cfg.orientation, "landscape");
        assert!(cfg.permissions.is_empty());
        assert_eq!(cfg.abis, [Abi::Arm64, Abi::X86_64]);
        assert_eq!(cfg.assets, None, "a missing directory packages nothing");

        let bad = serde_json::json!({"space3d": {"android": {"abis": ["mips"]}}});
        assert!(AndroidConfig::from_packages(&package("x", dir.path(), bad), &game).is_err());
        let bad = serde_json::json!({"space3d": {"android": {"orientation": "sideways!"}}});
        assert!(AndroidConfig::from_packages(&package("x", dir.path(), bad), &game).is_err());
    }

    #[test]
    fn legacy_cargo_apk_metadata_is_understood() {
        let dir = tempfile::tempdir().unwrap();
        let root = dir.path();
        std::fs::create_dir_all(root.join("assets")).unwrap();
        std::fs::create_dir_all(root.join("mobile")).unwrap();
        let game = package("my_game", root, Value::Null);
        let meta = serde_json::json!({"android": {
            "package": "com.acme.my_game",
            "apk_name": "my_game",
            "build_targets": ["aarch64-linux-android"],
            "assets": "../assets",
            "sdk": {"min_sdk_version": 28, "target_sdk_version": 35},
            "application": {"label": "My Game", "activity": {"orientation": "landscape"}},
            "uses_permission": [{"name": "android.permission.INTERNET"}]
        }});
        let mobile = package("my_game-mobile", &root.join("mobile"), meta);
        let cfg = AndroidConfig::from_packages(&mobile, &game).unwrap();
        assert_eq!(cfg.application_id, "com.acme.my_game");
        assert_eq!((cfg.min_sdk, cfg.target_sdk), (28, 35));
        assert_eq!(cfg.orientation, "landscape");
        assert_eq!(cfg.permissions, ["android.permission.INTERNET"]);
        assert_eq!(cfg.assets, Some(root.join("mobile").join("../assets")));
    }

    #[test]
    fn gradle_project_packages_the_native_activity() {
        let dir = tempfile::tempdir().unwrap();
        let game = package("my_game", dir.path(), Value::Null);
        let mut cfg = AndroidConfig::from_packages(&game, &game).unwrap();
        cfg.label = "Tom & Jerry's".into();
        let files = gradle_project(
            &cfg,
            "my_game_mobile",
            "my_game",
            &GradleDefaults {
                jni_libs: "../target/android/my_game/jniLibs".into(),
                assets: Some("../assets".into()),
            },
        );
        let file = |name: &str| {
            files
                .iter()
                .find(|(p, _)| p == Path::new(name))
                .map(|(_, c)| c.as_str())
                .unwrap_or_else(|| panic!("no {name}"))
        };
        let build = file("build.gradle.kts");
        assert!(build.contains(&format!("id(\"com.android.application\") version \"{AGP_VERSION}\"")));
        assert!(build.contains("applicationId = \"com.example.my_game\""));
        assert!(build.contains("getOrElse(\"../target/android/my_game/jniLibs\")"));
        assert!(build.contains("getOrElse(\"../assets\")"));
        for property in GRADLE_PROPERTIES {
            assert!(build.contains(&format!("gradleProperty(\"{property}\")")), "{property}");
        }
        let manifest = file("src/main/AndroidManifest.xml");
        assert!(manifest.contains(r#"android:name="android.app.lib_name" android:value="my_game_mobile""#));
        assert!(manifest.contains("android:label=\"Tom &amp; Jerry&apos;s\""));
        assert!(manifest.contains("android:hasCode=\"false\""));
        assert!(manifest.contains("android.permission.INTERNET"));
        assert!(!manifest.contains("android:icon"));
        assert!(file("settings.gradle.kts").contains("rootProject.name = \"my_game\""));
        assert_eq!(gradle_task(false, false), "assembleDebug");
        assert_eq!(gradle_task(true, true), "bundleRelease");
        assert_eq!(kotlin_string("a\"$b"), r#""a\"\$b""#);
    }

    #[test]
    fn writes_only_changed_files_and_finds_own_projects() {
        let dir = tempfile::tempdir().unwrap();
        let files = vec![(PathBuf::from("a/b.txt"), "one".to_owned())];
        write_files(dir.path(), &files).unwrap();
        let path = dir.path().join("a/b.txt");
        let before = std::fs::metadata(&path).unwrap().modified().unwrap();
        write_files(dir.path(), &files).unwrap();
        assert_eq!(std::fs::metadata(&path).unwrap().modified().unwrap(), before);
        write_files(dir.path(), &[(PathBuf::from("a/b.txt"), "two".to_owned())]).unwrap();
        assert_eq!(std::fs::read_to_string(&path).unwrap(), "two");

        assert_eq!(own_gradle_project(dir.path()), None);
        std::fs::create_dir_all(dir.path().join("android")).unwrap();
        std::fs::write(dir.path().join("android/build.gradle.kts"), "").unwrap();
        assert_eq!(own_gradle_project(dir.path()), Some(dir.path().join("android")));
        std::fs::write(dir.path().join("x.apk"), "").unwrap();
        assert_eq!(outputs(dir.path(), "apk"), [dir.path().join("x.apk")]);
    }
}
